def set_run_font(run, name="Times New Roman", size=12, bold=False, italic=False, color=None):
    run.font.name = name
    run._element.rPr.rFonts.set(qn("w:ascii"), name)
    run._element.rPr.rFonts.set(qn("w:hAnsi"), name)
    run.font.size = Pt(size)
    run.font.bold = bold
    run.font.italic = italic
    if color is not None:
        run.font.color.rgb = RGBColor(*color)
    return None


def add_text(paragraph, text, **kwargs):
    run = paragraph.add_run(text)
    set_run_font(run, **kwargs)
    return run


def body(doc, text, first_line=True):
    paragraph = doc.add_paragraph()
    paragraph.alignment = WD_ALIGN_PARAGRAPH.JUSTIFY
    paragraph.paragraph_format.space_after = Pt(8)
    paragraph.paragraph_format.space_before = Pt(0)
    paragraph.paragraph_format.line_spacing = 1.15
    if first_line:
        paragraph.paragraph_format.first_line_indent = Cm(0.75)
    add_text(paragraph, text)
    return paragraph


def heading(doc, text, level):
    paragraph = doc.add_heading(text, level=level)
    for run in paragraph.runs:
        set_run_font(
            run,
            size=14 if level == 1 else 12,
            bold=True,
            color=(0, 0, 0),
        )
    paragraph.paragraph_format.space_before = Pt(12)
    paragraph.paragraph_format.space_after = Pt(6)
    return paragraph


def equation(doc, text):
    paragraph = doc.add_paragraph()
    paragraph.alignment = WD_ALIGN_PARAGRAPH.CENTER
    paragraph.paragraph_format.space_before = Pt(2)
    paragraph.paragraph_format.space_after = Pt(2)
    add_text(paragraph, text, italic=True)
    return paragraph


def caption(doc, text):
    paragraph = doc.add_paragraph()
    paragraph.alignment = WD_ALIGN_PARAGRAPH.JUSTIFY
    paragraph.paragraph_format.space_before = Pt(2)
    paragraph.paragraph_format.space_after = Pt(10)
    paragraph.paragraph_format.line_spacing = 1.0
    add_text(paragraph, text, size=10)
    return paragraph


def shade(cell, hex_color):
    tc_pr = cell._tc.get_or_add_tcPr()
    shd = OxmlElement("w:shd")
    shd.set(qn("w:val"), "clear")
    shd.set(qn("w:color"), "auto")
    shd.set(qn("w:fill"), hex_color)
    tc_pr.append(shd)


def add_table(doc, title, headers, rows):
    caption(doc, title)
    table = doc.add_table(rows=1, cols=len(headers))
    table.style = "Table Grid"
    for index, header in enumerate(headers):
        cell = table.rows[0].cells[index]
        cell.text = ""
        paragraph = cell.paragraphs[0]
        add_text(paragraph, header, size=9, bold=True, color=(255, 255, 255))
        shade(cell, "1F4E79")
    for row in rows:
        cells = table.add_row().cells
        for index, value in enumerate(row):
            cells[index].text = ""
            add_text(cells[index].paragraphs[0], str(value), size=9)
    doc.add_paragraph()
    return table


def add_figure(doc, path, text):
    if path.is_file():
        paragraph = doc.add_paragraph()
        paragraph.alignment = WD_ALIGN_PARAGRAPH.CENTER
        run = paragraph.add_run()
        run.add_picture(str(path), width=Cm(15.5))
    else:
        body(doc, f"[Figure file not found: {path}]", first_line=False)
    caption(doc, text)


def reference(doc, text):
    paragraph = doc.add_paragraph()
    paragraph.paragraph_format.left_indent = Cm(0.75)
    paragraph.paragraph_format.first_line_indent = Cm(-0.75)
    paragraph.paragraph_format.space_after = Pt(4)
    paragraph.paragraph_format.line_spacing = 1.0
    paragraph.alignment = WD_ALIGN_PARAGRAPH.JUSTIFY
    add_text(paragraph, text, size=11)
    return paragraph


def footer(section):
    paragraph = section.footer.paragraphs[0]
    paragraph.alignment = WD_ALIGN_PARAGRAPH.CENTER
    add_text(
        paragraph,
        "Tiwari and Guru — Tilaiya monthly soil loss and sediment delivery",
        size=9,
        italic=True,
    )



def build():
    doc = Document()
    section = doc.sections[0]
    section.top_margin = Cm(2.4)
    section.bottom_margin = Cm(2.4)
    section.left_margin = Cm(2.5)
    section.right_margin = Cm(2.5)
    section.page_width = Cm(21.0)
    section.page_height = Cm(29.7)
    footer(section)
    normal = doc.styles['Normal']
    normal.font.name = 'Times New Roman'
    normal.font.size = Pt(12)
    title = doc.add_paragraph()
    title.alignment = WD_ALIGN_PARAGRAPH.CENTER
    add_text(title, 'Spatiotemporal Soil Erosion Dynamics and Sediment Connectivity in a Data-Scarce Monsoon Catchment: An Integrated Framework Coupling Sentinel-1 SAR Time-Series, Stacking Ensembles, and Explainable AI', size=14, bold=True)
    authors = doc.add_paragraph()
    authors.alignment = WD_ALIGN_PARAGRAPH.CENTER
    add_text(authors, 'Mukesh Kumar Tiwari', size=12, bold=True)
    add_text(authors, ' a,*', size=12)
    add_text(authors, ', Prabhat Kumar Guru', size=12, bold=True)
    add_text(authors, ' b', size=12)
    for line in ('a School of Natural Resource Management, ICAR–Indian Agricultural Research Institute, Jharkhand, Gauria Karma, Hazaribagh 825405, Jharkhand, India', 'b School of Natural Resource Management, ICAR–Indian Agricultural Research Institute, Jharkhand, Gauria Karma, Hazaribagh 825405, Jharkhand, India', '* Corresponding author. E-mail: Mukesh.tiwari1@icar.org.in; Tiwari.iitkgp@gmail.com. ORCID: 0000-0003-0385-4426.', 'E-mail: prabhatkumarguru@gmail.com.'):
        line_p = doc.add_paragraph()
        line_p.alignment = WD_ALIGN_PARAGRAPH.CENTER
        add_text(line_p, line, size=10, italic=True)
    heading(doc, 'Abstract', 1)
    body(doc, 'In a monsoon catchment, most soil loss falls in a few wet months, yet maps of the Damodar and the Barakar are annual, and reservoir studies report inflow to Tilaiya without showing which month or which slope produced the sediment. Optical cover is also hardest to obtain in the cloudy months, when erosivity is highest, and soil detached on a hillslope is not the same quantity as sediment stored in the reservoir. In this paper, spatiotemporal soil erosion dynamics means the spatial pattern and the month-to-month variation of RUSLE-estimated soil loss during January–December 2025, not a long-term field record. Monthly estimates were calculated for sub-watershed 2A219, a 715 km² headwater covering 73 percent of the 984 km² dam catchment. Annual erosivity followed a published Arnoldus equation and was allocated among months by the square of monthly rainfall, giving 6,854 to 12,083 MJ mm ha⁻¹ h⁻¹ yr⁻¹ on the five rainfall cells. That monthly factor is not storm EI30. July and August cover is an interpolation between June and September, not an observed canopy, because a radar index fitted outside those months had R² = 0.033. The monthly figures for sub-watershed 2A219, a 715 km² headwater, are scenario calculations for one year. One integer-metre scenario, using the published slope-length raster and a heuristic erodibility factor, has a mean of 136 t ha⁻¹ yr⁻¹, a median of 21.7, and a structural delivery volume of 1.03 × 10⁴ m³ yr⁻¹. Static erodibility lowers that mean to 119. A standard slope-length equation gives 103 on the integer-metre elevation and 119 on Copernicus GLO-30, and the wider set of calculated means runs from 87 to 346 t ha⁻¹ yr⁻¹. Across those scenarios the wet-season months dominate, gross hillslope volume stays above the published reservoir rates, and the structural yield stays far below them. Because plot measurements, sediment-gauge records, and reservoir bathymetry were unavailable, these figures are model scenarios for potential sheet-and-rill loss and structural connectivity, not measured erosion or reservoir sedimentation.', first_line=False)
    body(doc, 'Keywords: monthly soil loss; RUSLE; Sentinel-1; sediment connectivity; stacking ensemble; Tilaiya Reservoir', first_line=False)
    heading(doc, '1. Introduction', 1)
    body(doc, 'In this study, spatiotemporal soil erosion dynamics means the spatial pattern and the intra-annual variation of RUSLE-estimated soil loss during 2025. The term does not mean a long-term observational record or a direct field measurement. Water erosion is the main form of mapped land degradation in India, and the sediment it produces reduces reservoir storage. Bhattacharyya et al. (2015) reported 147 million hectares of degraded land, of which 94 million hectares are affected by water erosion. Most maps of this process use the Universal Soil Loss Equation or its revision (Wischmeier and Smith, 1978; Renard et al., 1997). Alewell et al. (2019) found such studies in 109 countries and listed four recurring limits: the model estimates detachment rather than measured sediment yield, satellite data are finer than the original field plots, monitoring is scarce, and uncertainty is often left out. Borrelli et al. (2021) reviewed 3,030 modelling records from 1994 to 2017 and found that about 41 percent used the (R)USLE family, with India among six countries that together account for about half of the applications. A review of 100 USLE studies in India found that nearly all of them mis-specified at least one factor, that errors in the rainfall factor were common, and that most of the studies were in eastern India, the region drained by the Damodar and its Barakar tributary (Majhi et al., 2021).')
    body(doc, 'In a monsoon climate, most of the erosion falls in a few wet months, so an annual map hides the season that matters for conservation. Where rainfall intensity is measured, monthly erosivity shows when cover and tillage are most needed, and in Europe the seasonal peak is several times the winter value (Ballabio et al., 2017). For India, Tiwari et al. (2015) mapped long-term erosivity from monthly rainfall at 52 stations and Pai et al. (2014) provide daily rainfall on a 0.25° grid, but neither product is a storm EI30 series for 2025. Monthly totals can still be converted to erosivity with the Modified Fournier index and the equations of Arnoldus (1977, 1980) and Renard and Freimund (1994). Chen et al. (2023) showed that these equations are often copied with the wrong coefficients, so the equation used here is stated in full. Cover is the other factor that changes through the year. A satellite C factor depends on the vegetation index and on the coefficient that converts the index to C (Huete, 1988; Benavidez et al., 2018; Phinzi and Ngetar, 2019), and optical indices need cloud-free images, which are hardest to obtain in the wet months. Sentinel-1 remains available through cloud (Torres et al., 2012), and VV and VH can be combined into a radar vegetation index (Kim and van Zyl, 2009). In the 2025 record, July has two Sentinel-2 scenes and nine Sentinel-1 scenes. Radar cover was calculated for July and August, but it does not follow the optical index, so those two months in the reported maps are interpolated from June and September.')
    body(doc, 'Tilaiya Dam, on the Barakar River, was inaugurated on 21 February 1953 under the Damodar Valley Corporation, which gives the dam catchment as 984 km². The Key Biodiversity Area factsheet gives the same area, 98,420 ha (Damodar Valley Corporation, n.d.; Key Biodiversity Areas, n.d.). Sedimentation at the reservoir has already been estimated, so a new soil-loss map can be read against those figures. Sardar et al. (2014) calibrated SWAT to monthly inflow at Tilaiya and Maithon and to runoff and sediment at Banha and Karso, with agreement within 10 percent. The publisher abstract prints a Tilaiya sedimentation rate as 0.76 mm3/year. The typeset PDF was not available, so that rate is not used as a numerical comparison in this paper. Dutta et al. (2017) calibrated SWAT to Tilaiya streamflow for 1991–1995, checked it for 1996–2000, and estimated that dead storage would fill in 89 years from the year 2000. Central Water Commission (2021), publication CWC/2021/147, surveyed live storage from satellite data and reported a 2021 live capacity of 131.235 million m³ at full reservoir level against an original 199.89 million m³, a loss of 68.655 million m³ (34.3 percent) over 68 years, or about 1.01 million m³ yr⁻¹. The survey was not checked on the ground. Hillslope studies in the same river system are annual. Pandey et al. (2007) applied the USLE on 200 m cells in the Karso watershed of Hazaribagh and came within 1.37 to 13.85 percent of measured sediment yield. Biswas and Pani (2015) mapped annual RUSLE soil loss for the Barakar basin, where values above 100 t ha⁻¹ yr⁻¹ covered 0.08 percent of the basin, and named Tilaiya without calculating a delivery ratio. Ghosh et al. (2025) mapped the Damodar basin and reported mean soil loss of 12.86 t ha⁻¹ yr⁻¹ in 2017 and 12.06 t ha⁻¹ yr⁻¹ in 2024, without field measurements at that scale.')
    body(doc, 'These studies answer different questions. Annual maps average the monsoon into one value, and SWAT estimates how much sediment reaches the dam without showing which month or which slope produced it. Soil detached on a slope is not the load that leaves the catchment, because some of the material is stored along the path (Walling, 1983; Kinnell, 2008), so gross soil-loss maps and measured yields have to be kept separate (de Vente et al., 2013; Alewell et al., 2019). Connectivity indices can link the two, but most of them describe the terrain and the flow paths rather than the sediment moved in a particular season (Borselli et al., 2008; Vigiak et al., 2012; Hamel et al., 2015; Heckmann et al., 2018). Biswas and Pani (2015) did not calculate delivery for the Barakar because they lacked sediment measurements, and Sardar et al. (2014) and Dutta et al. (2017) routed sediment to Tilaiya in SWAT rather than on a 12.5 m connectivity grid. This study addresses that gap for one year in the Tilaiya headwater by mapping soil loss month by month, testing whether radar cover can stand in for optical cover, and reporting delivery in cubic metres beside the reservoir rates.')
    body(doc, 'The calculations use 2025 data for sub-watershed 2A219, an area of 715 km², or 73 percent of the 984 km² dam catchment. The remaining area is not added by scaling. Monthly soil loss is the product of erosivity, erodibility, the LS factor, cover and support practice, and the annual total uses only pixels that are valid in all twelve months. In the reported maps, July and August cover is interpolated from June and September, and radar cover is kept only as a sensitivity test. A Borselli connectivity index and a delivery ratio are then calculated to the edge of the mask and set beside the live-storage loss of about 1.01 million m³ yr⁻¹ (Central Water Commission, 2021). The Sardar et al. (2014) rate is not used numerically, because its printed unit could not be verified from the typeset PDF. A stacking model is used only as a surrogate of the annual RUSLE surface, and the SHAP values explain the XGBoost member of that surrogate (Section 6.4). The scores describe agreement with the model-generated RUSLE target (Lundberg and Lee, 2017; Roberts et al., 2017; Ploton et al., 2020; Mallick et al., 2025).')
    body(doc, 'The objectives are to map monthly soil loss for 2025 with the corrected Arnoldus erosivity equation and to compare June and July on the same pixels; to compare interpolated optical cover with radar cover and to report the Renard and Freimund annual total as a second published estimate; and to calculate a structural delivery ratio and set the modelled volume beside the published Tilaiya reservoir rates. The paper tests these calculations. It does not provide a calibrated sediment budget, which would require storm erosivity, a reservoir shoreline, and a delivery ratio fitted to the storage survey. Those steps are identified later as work that has not been done.')
    heading(doc, '2. Literature review and research gaps', 1)
    heading(doc, '2.1 Annual maps and reservoir inflow in the Damodar headwaters', 2)
    body(doc, 'Section 1 gives the national and global context, but an annual mean still needs care. García-Ruiz et al. (2015) compiled field measurements, and Borrelli et al. (2021) report median gross rates of 9.6 t ha⁻¹ yr⁻¹ for the USLE and 12.6 t ha⁻¹ yr⁻¹ for the RUSLE, with a median of about 6.4 t ha⁻¹ yr⁻¹ for SWAT applications classed as net erosion. A value in that range is a modelled soil-loss rate, not a reservoir siltation rate. Majhi et al. (2021) also found that many Indian USLE studies are described too briefly to repeat, and they warned against mixing gross maps with measured yields. The Damodar headwaters contain both kinds of result.')
    body(doc, 'On the mapping side, Pandey et al. (2007) applied the USLE on 200 m cells in the Karso watershed of Hazaribagh, within the Barakar system, and compared the grid sediment yield with observations, with a deviation of 1.37 to 13.85 percent. That remains the nearby example of a USLE sediment yield checked against a measurement. Biswas and Pani (2015) mapped annual RUSLE soil loss for the whole Barakar basin and found that rates above 100 t ha⁻¹ yr⁻¹ covered 0.08 percent of the basin, with the high values following the slope-length and erodibility factors. They discussed reservoir capacity using Damodar Valley Corporation surveys of Maithon and named Tilaiya as the upstream impoundment, but they did not calculate a delivery ratio. Ghosh et al. (2025) repeated the annual calculation for the whole Damodar basin in Google Earth Engine and reported mean soil loss of 12.86 t ha⁻¹ yr⁻¹ in 2017 and 12.06 t ha⁻¹ yr⁻¹ in 2024, attributing the change to rainfall, although field observations were not available at that basin scale.')
    body(doc, 'At the reservoir, Sardar et al. (2014) calibrated SWAT to monthly inflow at Tilaiya and Maithon and to runoff and sediment at Banha and Karso, with agreement within 10 percent. The abstract prints a sedimentation rate as mm3/year. The typeset PDF was not opened, so the rate is not used numerically here. The critical areas were compared with the sediment-yield-index map of the Damodar Valley Corporation at Hazaribagh. Dutta et al. (2017) calibrated SWAT to Tilaiya streamflow for 1991–1995, checked it for 1996–2000, and estimated that dead storage would fill in 89 years from the year 2000. These are reservoir-life estimates from a gauged model, and a hillslope map should be read against them rather than in their place.')
    body(doc, 'A further annual total for the whole basin would not close this gap. The published maps average the monsoon into one number. The SWAT studies estimate the sediment at the dam, but not the month, or the 12.5 m slope, that produced it. A monthly map for one recent year in the Tilaiya headwater is the calculation that links the two.')
    heading(doc, '2.2 Monthly erosivity without storm intensity', 2)
    body(doc, 'In the RUSLE, the rainfall factor is the annual sum of storm EI30. EI30 requires the rainfall intensity during each storm (Wischmeier and Smith, 1978; Renard et al., 1997). Where intensity data exist, monthly erosivity shows the period in which cover and tillage ought to be applied. Ballabio et al. (2017) mapped this quantity for Europe from sub-hourly rainfall. The seasonal peak was several times the winter value, so that an annual R factor conceals the months that matter most. Tiwari et al. (2015) prepared a long-term erosivity map for India from 101 years of monthly rainfall at 52 stations. That map is a national average. It does not give storm EI30 for 2025 on the 0.25° grid of the India Meteorological Department.')
    body(doc, 'The IMD grid does provide monthly totals. These can be converted to an R value with the Modified Fournier index, MFI = P² / Pannual, and the regressions of Arnoldus (1977, 1980) and Renard and Freimund (1994) (Fournier, 1960). The choice of equation affects the result. Majhi et al. (2021) found the R factor to be among the terms most often specified incorrectly. Chen et al. (2023) showed that one empirical erosivity equation has been copied with the wrong coefficients in many countries. A monthly map should therefore state its coefficients.')
    body(doc, 'The reported maps use the corrected Arnoldus (1977) equation in the form given by Chen et al. (2023). That equation was estimated for Morocco. It is not a fit to storms at Tilaiya, and it is not storm EI30. An earlier monthly power function used the coefficients 1.8219 and 1.211. No paper giving that pair was found, and those maps are therefore not the results reported here. The annual total is divided among the months in proportion to the square of monthly rainfall. Cell 1 still attains its peak in June. The other four cells attain their peak in July. On the wettest cell, July holds 0.57 of the annual total. Renard and Freimund (1994) provide a second annual total, fitted in the United States. That total is reported for comparison and is not used to draw the monthly maps.')
    heading(doc, '2.3 Cover when the optical record fails', 2)
    body(doc, 'The cover factor is what allows a monthly map to change through the year. Phinzi and Ngetar (2019) reviewed catchment studies that estimate this factor from remote sensing, and they concluded that the map is only as reliable as that step. Benavidez et al. (2018) made the same point for vegetation-index equations carried from one region to another. The index measures the canopy. The coefficient that converts it to C remains an assumption unless it is fitted locally. Optical indices are the usual source (Huete, 1988), and they require a clear view.')
    body(doc, 'In a monsoon headwater, cloud cover is greatest in the months of highest erosivity. Sentinel-1 C-band backscatter remains available in those months (Torres et al., 2012), and a radar vegetation index can be calculated from VV and VH (Kim and van Zyl, 2009). If the change of sensor is not stated, a fall in the cover factor can be mistaken for a fall in vegetation. For July and August, radar cover was calculated and was then set aside. The reported cover is interpolated from the optical factors of June and September. The coefficient 1.18 is not calibrated to local measurements of the canopy.')
    heading(doc, '2.4 A stack that recovers a RUSLE map', 2)
    body(doc, 'Mallick et al. (2025) trained a stacking model on RUSLE classes in the Kangsabati basin and explained it with SHAP, because a stack does not possess one set of Shapley values (Lundberg and Lee, 2017). Roberts et al. (2017) and Ploton et al. (2020) showed that a random split of nearby points underestimates the error of a map. A high score can mean only that the model has reconstructed the LS factor, the cover and the erodibility. Section 6.4 reports that check. It is not an estimate of erosion at Tilaiya.')
    heading(doc, '2.5 From detached soil to delivered sediment', 2)
    body(doc, 'Walling (1983) described the sediment delivery problem. Soil detached on a hillslope is not the load that leaves the catchment, because some of it is stored and the travel distance matters. Kinnell (2008) made the same point for the USLE. The equation estimates sheet and rill detachment on a slope. Sediment yield needs a second calculation. de Vente et al. (2013) found that gross-erosion maps and measured yields still answer different questions, and Alewell et al. (2019) listed this difference among the main open problems. Heckmann et al. (2018) reviewed the indices used for that second step. Nearly all of them describe the permanent pattern of connectivity. They do not measure how much sediment moves in a given season.')
    body(doc, 'Borselli et al. (2008) defined the index of connectivity as the log ratio of an upslope component to a downslope path cost, and Vigiak et al. (2012) compared that family of metrics with hillslope delivery. Hamel et al. (2015) put a sigmoid on the index inside the InVEST sediment model, with a maximum delivery ratio, a threshold, and a slope parameter that are chosen rather than fitted in most applications. Biswas and Pani (2015) stopped before this step in the Barakar because a delivery ratio could not be supported with the sediment data they had. Sardar et al. (2014) and Dutta et al. (2017) carried sediment to Tilaiya inside SWAT, at the scale of sub-watersheds and reservoir inflow, without a 12.5 m connectivity surface.')
    body(doc, 'Without a sediment gauge, the calculation that can still be made is a structural delivery ratio. It is weighted by mean monthly cover, summed to the edge of the watershed mask, and reported as a modelled yield. In the terms of Heckmann et al. (2018), this is a static description of the terrain. It uses one cover weight for the year, and the paths end at the mask edge rather than at a surveyed shoreline. This fraction is set beside the Central Water Commission live-storage loss. It is not set beside the Sardar et al. (2014) rate, because that printed unit was not verified.')
    heading(doc, '2.6 What the present study tests', 2)
    body(doc, 'The present study tests three calculations for 2025. It is not a calibrated sediment budget for Tilaiya. The first is a monthly soil-loss map on the 715 km² mask, using the corrected Arnoldus equation. The second compares interpolated optical cover with radar cover in July and August. The third is structural delivery to the edge of the mask, reported in tonnes and in cubic metres beside the live-storage survey of the Central Water Commission (2021). The Sardar et al. (2014) rate is cited as a SWAT study and is not used as a volume benchmark. The stacking model is reported in Section 6.4.')
    heading(doc, '3. Study area', 1)
    body(doc, 'The analysis mask is sub-watershed 2A219, the headwater of the Tilaiya Reservoir on the Chota Nagpur plateau in eastern India. The grid contains 4,576,196 cells of 12.5 m within that boundary, giving an area of 715.0 km². The Damodar Valley Corporation lists the catchment of Tilaiya Dam as 984 km², and the Key Biodiversity Area factsheet for the reservoir gives the same drainage area, 98,420 ha (Damodar Valley Corporation, n.d.; Key Biodiversity Areas, n.d.). The mask used here is 73 per cent of that official catchment. Sediment yields from the mask are therefore not yields from the whole catchment of the dam, and the missing 269 km² are not filled by scaling. The mask lies between approximately 24.09° N and 24.39° N and 85.14° E and 85.49° E, in WGS 84 / UTM zone 45N. It drains to the Tilaiya impoundment on the Barakar, which was inaugurated on 21 February 1953. The relief is that of a plateau. Elevations from the ALOS PALSAR digital elevation model are stored in whole metres, and they include broad flats as well as steeper valley sides. The soils used here are the SoilGrids representations of texture and organic carbon (Poggio et al., 2021), resampled to the 12.5 m grid. The land cover is a mixture of cultivation, fallow and woody vegetation typical of this plateau, and the support-practice factor retains that spatial pattern as a static grid. Figure 1 shows the analysis mask.')
    add_figure(doc, ((FIGURES / 'maps') / 'Tilaiya_2A219_study_area.png'), 'Figure 1. Study area, sub-watershed 2A219 (715 km²). This polygon is the boundary used for soil loss, connectivity, and the reported areas. The frame is WGS 84 / UTM zone 45N.')
    body(doc, 'The rainfall is monsoonal. In 2025, the five 0.25° cells that intersect the watershed received 1,090–1,443 mm. June to October supplied almost the whole of the annual total. January, February and December were dry on every cell of the watershed. The catchment is treated as ungauged for sediment. No plot record, stream-gauge record, or reservoir-bathymetry record has been used.')
    heading(doc, '4. Data', 1)
    body(doc, 'All rasters were aligned to one grid: 2,777 columns by 2,677 rows, cell size 12.5 m, upper-left origin 311,579.4375 E, 2,698,245.25 N, EPSG:32645. New rasters use NoData −9999. The digital elevation model uses NoData 32767. A cell area is 156.25 m², or 0.015625 ha. The 12.5 m grid is a common calculation frame. It is not the resolution at which every input is observed. Rainfall and erosivity are constant inside each 0.25° IMD cell (Pai et al., 2014). SoilGrids texture, organic carbon, and the base erodibility derived from them are 250 m information placed on the 12.5 m cells (Poggio et al., 2021). Elevation is a 12.5 m product, but the values used here are stored in whole metres, so flats have no unique slope and the LS factor is exactly zero on those cells. The LS factor, flow direction, and the monthly satellite composites are the layers that can vary from cell to cell. Soil-loss maps at 12.5 m are therefore a fine-grid representation of mixed-resolution inputs, not a 12.5 m measurement of erosion.')
    add_table(doc, 'Table 1. Data used to build the 2025 monthly soil-loss and connectivity maps.', ['Data', 'Source and resolution', 'Role in the present study'], [['Elevation', 'ALOS PALSAR RTC DEM, 12.5 m (Rosenqvist et al., 2007)', 'Slope, flow paths, hillshade'], ['Rainfall', 'IMD daily grid, 0.25°, 2025 (Pai et al., 2014)', 'Monthly and annual erosivity'], ['Sentinel-2', 'Copernicus optical scenes, 2025, Google Earth Engine', 'SAVI and optical cover'], ['Sentinel-1', 'Copernicus C-band GRD, VV and VH, 2025', 'RVI and the wetness index for Km'], ['Soil', 'SoilGrids 2.0, 250 m (Poggio et al., 2021)', 'Texture, SOC, and base erodibility K'], ['LS, C, P, NDVI, annual A', 'Aligned 12.5 m annual RUSLE layers for this catchment', 'Static factors and the machine-learning target'], ['Watershed', 'Sub-watershed 2A219 boundary', 'Analysis mask and map frame']])
    body(doc, 'Sentinel-2 reflectance was divided by 10,000 before the vegetation index, because the soil-adjustment term is defined on reflectance. Sentinel-1 GRD values were converted from decibels to linear power before the radar vegetation index. Optical scenes are the Copernicus collection COPERNICUS/S2_SR_HARMONIZED (Drusch et al., 2012). A month keeps scenes with cloudy-pixel percentage below 80, and the scene-classification layer then masks classes 3, 8, 9, 10, and 11. The monthly optical image is the median of the remaining pixels. Radar scenes are COPERNICUS/S1_GRD, interferometric wide swath, with both VV and VH (Torres et al., 2012). The monthly radar image is the median of VV and VH in decibels. No orbit-direction split, speckle filter, incidence-angle correction, or additional terrain correction was applied. Scene counts after these filters are given in Table 2. July retains two Sentinel-2 scenes and August retains five, against nine and ten Sentinel-1 scenes in those months.')
    add_table(doc, 'Table 2. Scenes retained in each month of 2025 after filtering.', ['Month', 'Sentinel-2', 'Sentinel-1', 'Month', 'Sentinel-2', 'Sentinel-1'], [['January', '12', '11', 'July', '2', '9'], ['February', '10', '9', 'August', '5', '10'], ['March', '14', '11', 'September', '10', '9'], ['April', '15', '9', 'October', '10', '11'], ['May', '16', '10', 'November', '13', '10'], ['June', '5', '11', 'December', '15', '10']])
    heading(doc, '5. Methods', 1)
    body(doc, 'The calculations evaluate the intra-annual variation of RUSLE-estimated soil loss from January to December 2025, together with a structural connectivity scenario on the same mask. RUSLE-estimated soil loss is potential sheet-and-rill detachment. No plot measurement is paired with these values. The 12.5 m grid is a common computational frame. Rainfall is supplied at 0.25° and soil information at about 250 m, so a pixel value is a fine-grid representation of coarser inputs, not a 12.5 m observation of erosion.')
    heading(doc, '5.1 Monthly rainfall erosivity', 2)
    body(doc, 'Erosivity was calculated for each IMD cell from its own monthly rainfall. The annual value is the corrected Arnoldus (1977) equation, in the form given by Chen et al. (2023):', first_line=False)
    equation(doc, 'R = 17.02 × 10^(1.50 × log₁₀(Σ Pₘ² / P) − 0.8188)')
    equation(doc, 'Rₘ = R × (Pₘ² / Σ Pₘ²)')
    body(doc, 'P and Pₘ are in millimetres. R is in MJ mm ha⁻¹ h⁻¹ yr⁻¹, and Rₘ is the monthly share of that annual total. A dry month has Rₘ = 0, and the twelve monthly values sum to R. The split follows the monthly terms inside the Modified Fournier index (Fournier, 1960; Arnoldus, 1980). It is not a second regression. Arnoldus (1977) estimated the annual equation for Morocco. It was not fitted to storms or erosion plots at Tilaiya, and it is not the storm EI30 of RUSLE (Wischmeier and Smith, 1978; Renard et al., 1997). The monthly factor is an empirical allocation of that annual estimate in proportion to the square of monthly rainfall. July and August estimates are sensitive to that allocation. They are not measured monthly rainfall erosivity. An earlier function, Rₘ = 1.8219 × (Pₘ² / P)^1.211, has no identified source. Those stored erosivity rasters were not used for Section 6. Because soil loss is proportional to erosivity when the other factors are unchanged, each stored monthly soil-loss value was multiplied by the ratio of the new Rₘ to the stored Rₘ. July and August were also multiplied by the ratio of interpolated optical cover to radar cover. The new rasters are in output/rasters/SoilLoss_Arnoldus. The original SoilLoss rasters were left in place. Renard and Freimund (1994) give a second published annual total from the same rainfall. Those equations were fitted in the United States. They are reported in Tables 4 and 8 and were not used to draw the monthly maps.')
    body(doc, 'Two spatial supports were calculated and were not mixed. A six-cell mean inside an expanded bounding box totals 1,307 mm in 2025 and is a catchment time series with no map. The maps use the five 0.25° cells whose polygons intersect the watershed. Each 12.5 m pixel receives the value of the IMD cell that covers it. There is no interpolation between cells. The sixth cell, centred at 85.50° E, 24.50° N, falls in the bounding box but does not intersect the watershed and is excluded.')
    heading(doc, '5.2 Cover management and the within-month stretch of K', 2)
    body(doc, 'The soil-adjusted vegetation index uses the standard soil-adjustment factor L = 0.5 (Huete, 1988):', first_line=False)
    equation(doc, 'SAVI = ((NIR − Red) / (NIR + Red + 0.5)) × 1.5')
    body(doc, 'Red is Sentinel-2 band 4 and NIR is band 8. The dual-polarisation radar vegetation index, after conversion of decibels to linear power, is', first_line=False)
    equation(doc, 'σ⁰ = 10^(dB/10)')
    equation(doc, 'RVI = 4 × VH / (VV + VH)')
    body(doc, 'This is the dual-polarisation form of the radar vegetation index associated with Kim and van Zyl (2009), applied here to the Sentinel-1 VV and VH pair. The same cover equation is used in every month:', first_line=False)
    equation(doc, 'Cₘ = clip(1 − 1.18 × canopy index, 0.001, 1)')
    body(doc, 'The canopy index is SAVI from January to June and from September to December. It is RVI in July and August. RVI is clipped to 0–1 before the equation so that Cₘ stays inside 0.001–1. The equation reaches the floor of 0.001 once the canopy index exceeds (1 − 0.001) / 1.18, about 0.847. The switch is by calendar month, not by a per-pixel cloud test: a clear July pixel still receives the radar-based factor. June has only five clear optical scenes but remains on SAVI, because the rule names July and August rather than a scene-count threshold. SAVI and RVI were compared on 800,000 pixels from the ten months that use SAVI. A line of SAVI on RVI has slope 0.098, intercept 0.235, and R² = 0.033, so the radar index does not recover the optical index. At the sample points their means are 0.309 and 0.693. A larger index produces a smaller Cₘ, so July and August can step down relative to a neighbouring SAVI month. The SAVI-based factor is retained as Cₘ, optical in every month so that step can be inspected. The coefficient 1.18 is an adopted linear form, not a local calibration (Benavidez et al., 2018). The stored July and August layers still use RVI. The reported maps replace July and August with cover interpolated from June and September, because R² = 0.033. That weak fit is a reason to avoid treating radar cover as optical cover. It does not show that a blend of June and September is the canopy that was present in July or August. The interpolated values are a scenario, not observed canopy conditions. Radar cover is retained only as a sensitivity case. Other interpolation weights were not tested.')
    body(doc, 'Base erodibility K is the aligned annual K layer. Monthly erodibility raises K where Sentinel-1 VV is high relative to that month’s own distribution, which is the expected direction for a wetter surface. The index is a percentile stretch, not a dielectric retrieval:', first_line=False)
    equation(doc, 'θ = clip((VV − VVₚ₅) / (VVₚ₉₅ − VVₚ₅), 0, 1)')
    equation(doc, 'Kₘ = K × (1 + 0.25 × θ)')
    body(doc, 'On the soil-loss maps the 5th and 95th percentiles are calculated inside the watershed, separately for each month. Because θ is stretched to 0–1 inside every month, a wetter month and a drier month can have the same θ distribution even when their VV levels differ. The point table used for machine learning was built with percentiles of the full monthly raster, so a point value of Kₘ is not identical to the map pixel at the same location. That difference was not removed. The coefficient 0.25 sets the largest monthly increase at 25% of base K. It is a heuristic. In RUSLE, K is a soil property, and moisture would more properly enter through runoff. Kₘ should be read as a within-month rescaling of K, not as a measurement of changing soil erodibility and not as a moisture series. The within-month percentile stretch removes absolute differences in backscatter between months, and the coefficient 0.25 is assumed. Section 6.7 repeats the annual sum with erodibility held at base K. The reported maps keep the heuristic inside the primary scenario. Km is not interpreted as observed erodibility. Sentinel-1 was not corrected for incidence angle or terrain, so the spatial pattern of this stretch can follow slope and aspect.')
    heading(doc, '5.3 Monthly soil loss', 2)
    body(doc, 'Monthly soil loss multiplies the spatial erosivity raster by the monthly erodibility and cover and by the static LS factor and the support-practice factor. LS here is slope length and steepness together, not the length factor L alone:', first_line=False)
    equation(doc, 'Aₘ = Rₘ × Kₘ × LS × Cₘ × P')
    body(doc, 'A pixel is NoData when K, LS, P, Cₘ, VV, or Rₘ is missing, or when the product is negative. The annual map is the sum of the twelve months only where all twelve months are valid. A missing month is not replaced by zero and is not imputed. About 30,208 watershed pixels lack K, LS, or P in every month. June has 111,194 missing pixels and September 347,762, from gaps in the monthly satellite layers. Monthly means use each month’s own valid pixels. The annual mean and the gross erosion total use only the twelve-month intersection, and the June–July comparison in Section 6.2 uses that same common support. Missingness is not assumed to be random. Figure 25 and Table 17 compare the pixels inside and outside that twelve-month support by elevation, D8 slope, October NDVI, and the annual cover factor. A classified land-cover map was not available. Annual classes follow the breaks 0–5, 5–15, 15–30, 30–50, 50–100, and greater than 100 t ha⁻¹ yr⁻¹.')
    heading(doc, '5.4 Sample and stacking ensemble', 2)
    body(doc, 'The machine-learning target is annual RUSLE soil loss on the aligned annual layer, not the 2025 monthly sum. Valid pixels for sampling numbered 4,527,896. A pixel was kept when the predictors and the soil-loss value were finite and soil loss was at least zero. The design is a class-stratified sample of 12,697 points, random seed 42 (Table 3). The source annual table did not store coordinates, so this is a new draw of that design rather than a recovery of an earlier point list. Each point stores easting, northing, row, column, and a 2 km spatial-block identifier. The split is 8,888 training points and 3,809 holdout points, stratified by erosion class. The holdout is a random stratified split. Spatial blocking is used only inside training.')
    add_table(doc, 'Table 3. Class-stratified sample drawn from the annual RUSLE soil-loss surface.', ['Class', 'Soil loss (t ha⁻¹ yr⁻¹)', 'Pixels', 'Percent', 'Samples'], [['E1', '0–5', '2,755,730', '60.86', '7,729'], ['E2', '5–15', '1,025,338', '22.64', '2,875'], ['E3', '15–30', '463,379', '10.23', '1,299'], ['E4', '30–50', '162,746', '3.59', '456'], ['E5', '50–100', '88,247', '1.95', '247'], ['E6', '>100', '32,456', '0.72', '91'], ['Total', '—', '4,527,896', '100', '12,697']])
    body(doc, 'Two predictor sets were trained on the same points and the same target. Reduced Integrated uses LS, SOC, C, P, NDVI, and K. Dynamic Integrated uses LS, R, Kₘ, Cₘ, P, RVI, SAVI, and SOC. In the second set, Kₘ, Cₘ, RVI, and SAVI are the annual means of the monthly factors at the point, and Kₘ uses the full-raster percentiles described above. Level-0 models are XGBoost (500 trees, maximum depth 6, learning rate 0.03, subsample 0.8), CatBoost (600 iterations, depth 6, learning rate 0.04, L2 leaf regularisation 3), Random Forest (300 trees, maximum features equal to the square root of the number of predictors, minimum samples to split 4), and a multilayer perceptron with hidden layers of 100 and 50 units, ReLU activations, the Adam solver, L2 penalty 0.001, and early stopping. Perceptron inputs are standardised. Level-1 is a ridge regression with penalty 1.0 and an intercept, fitted only to out-of-fold Level-0 predictions. The folds are five GroupKFold splits on the 2 km blocks inside the training points. The holdout is not used to fit the ridge. Under the sum-of-squares definition used here, R² and the Nash–Sutcliffe efficiency are the same number.')
    heading(doc, '5.5 TreeSHAP', 2)
    body(doc, 'TreeSHAP (Lundberg and Lee, 2017) was applied to the XGBoost member of each stack, on the same 3,809 holdout points. For Reduced Integrated the explanation refers to the member whose holdout R² is 0.451. For Dynamic Integrated it refers to the member whose holdout R² is 0.411. Neither explanation describes the ridge blend or the perceptron. A cover threshold of 0.15 was tested because bare cover is often treated as a distinct management state. No holdout point has annual C below 0.15, and no holdout point has mean monthly Cm below 0.15.')
    heading(doc, '5.6 Connectivity and sediment delivery', 2)
    body(doc, 'Structural connectivity follows Borselli et al. (2008). The upslope component combines the upslope area with the mean weight and mean slope of the upslope cells. The downslope component sums the flow length divided by the local weight and slope:', first_line=False)
    equation(doc, 'IC = log₁₀(Dᵤₚ / Ddown)')
    equation(doc, 'Dᵤₚ = C̄ × S̄ × √Aᵤₚ')
    equation(doc, 'Ddown = Σ dᵢ / (Cᵢ × Sᵢ)')
    body(doc, 'Flow is steepest-descent D8 on the raw elevation grid. Neighbours of equal elevation are not given an arbitrary direction. A flat cell is allowed to drain only towards a neighbour that already drains and whose raw elevation is equal or lower. Among those neighbours, the exit is the one with the lowest elevation after an 11-cell-radius box mean. The rule adds no uphill link, so the network has no loop. Cells on the boundary of the valid grid are outlets. An earlier trial that imposed a microscopic slope on integer-metre flats produced parallel drainage bands on the northern plateau and was discarded. Weight and slope are floored at 0.001 so the downslope term stays finite. The weight is the mean of the twelve monthly Cₘ layers.')
    body(doc, 'The sediment delivery ratio uses the sigmoid form of Vigiak et al. (2012), with the parameter values adopted for the present study:', first_line=False)
    equation(doc, 'SDR = 0.8 / (1 + exp((0.5 − IC) / 1.2))')
    equation(doc, 'SY = Σ (A × SDR × 0.015625)')
    equation(doc, 'Volume = SY / 1.45')
    body(doc, 'SY is in tonnes per year and A is in t ha⁻¹ yr⁻¹. The bulk density 1.45 t m⁻³ is an assumed dry bulk density, equal to 1.45 g cm⁻³. It was not measured on these soils. The same SDR grid is applied to the 2025 Arnoldus annual sum. The grid was not rebuilt. Paths end at the catchment outlet. No mask of the Tilaiya Reservoir shoreline was available, so the calculation is not a siltation volume for the reservoir water body.')
    heading(doc, '6. Results', 1)
    body(doc, 'Sections 6.1 to 6.6 describe one scenario: the published slope-length raster, heuristic monthly erodibility, interpolated July and August cover, and the corrected Arnoldus erosivity. The mean of 136 t ha⁻¹ yr⁻¹ and the structural volume of 1.03 × 10⁴ m³ yr⁻¹ belong to that scenario. Section 6.7 places them among the other cases that were calculated.')
    heading(doc, '6.1 Rainfall and erosivity in 2025', 2)
    body(doc, 'Annual rainfall on the five watershed cells ranged from 1,090 mm to 1,443 mm, and corrected Arnoldus erosivity on the same cells ranged from 6,854 to 12,083 MJ mm ha⁻¹ h⁻¹ yr⁻¹ (Table 4). The Renard and Freimund (1994) equations, which were fitted in the United States and are not used to draw the monthly maps, give 16,451 to 35,708 on that rainfall. The monsoon is not uniform across the watershed. Cell 1, in the south-west of the grid, received more rain in June (324 mm) than in July (272 mm), so its erosivity peaks in June, whereas the other four cells peak in July (Table 5). July rainfall on the watershed raster ranged from 272.4 mm to 480.1 mm, with a pixel-weighted mean of 336.1 mm and a pixel-weighted erosivity of 3,689 MJ mm ha⁻¹ h⁻¹ month⁻¹. Because the drier cells cover more of the watershed, this mean lies below the unweighted mean of the five cells. January, February and December are zero on every cell, and neither equation was fitted in this catchment. Figure 2 shows monthly rainfall and Figure 3 shows July.')
    add_table(doc, 'Table 4. Annual rainfall and published annual erosivity for the five IMD cells that intersect the watershed, 2025. The Arnoldus column is the equation used in the maps.', ['Cell', 'Longitude (°E)', 'Latitude (°N)', 'Rainfall (mm)', 'Arnoldus R', 'Renard and Freimund R'], [['1', '85.25', '24.00', '1,220', '8,133', '20,801'], ['2', '85.50', '24.00', '1,399', '11,610', '33,819'], ['3', '85.25', '24.25', '1,090', '6,854', '16,451'], ['4', '85.50', '24.25', '1,263', '9,504', '25,738'], ['5', '85.25', '24.50', '1,443', '12,083', '35,708']])
    add_table(doc, 'Table 5. Monthly share of the corrected Arnoldus annual total. Erosivity is in MJ mm ha⁻¹ h⁻¹ month⁻¹. The July share is the fraction of the annual total.', ['Cell', 'June Rₘ', 'July Rₘ', 'July share', 'Peak month'], [['1', '3,249', '2,302', '0.28', 'June'], ['2', '1,603', '5,111', '0.44', 'July'], ['3', '1,546', '3,154', '0.46', 'July'], ['4', '1,177', '4,997', '0.53', 'July'], ['5', '1,636', '6,904', '0.57', 'July']])
    add_figure(doc, ((FIGURES / 'maps') / 'Rainfall_monthly_2025.png'), 'Figure 2. Monthly rainfall in 2025. Each colour is constant inside an IMD 0.25° cell. January, February, and December are dry on every watershed cell.')
    add_figure(doc, ((FIGURES / 'maps') / 'Rainfall_July_2025.png'), 'Figure 3. Rainfall in July 2025. On the watershed cells the values range from 272.4 mm to 480.1 mm.')
    heading(doc, '6.2 Monthly RUSLE-estimated soil loss', 2)
    body(doc, 'Mean monthly RUSLE-estimated soil loss is negligible from November through February, rises through the pre-monsoon, and is concentrated in June, July and August (Table 6). The June, July and August means are 27.7, 65.4 and 21.5 t ha⁻¹. July and August use 4,154,545 pixels, because the interpolated cover needs both June and September. The July median is 9.92 t ha⁻¹ and the July 95th percentile is 261 t ha⁻¹. Mean cover falls from 0.636 in June to 0.584 in July and 0.532 in August. No July or August pixel on these maps sits on the cover floor of 0.001, and no July pixel has cover below 0.15. Mean Kₘ stays between 0.0393 and 0.0398 in every month, because each month is scaled to its own VV percentiles, so the lower January backscatter does not appear as a lower Kₘ. The annual mean, on the same 4,154,545 pixels (90.8 percent of the watershed), is 136 t ha⁻¹ yr⁻¹ and the median is 21.7 t ha⁻¹ yr⁻¹ (Table 8). Forty-eight percent of the annual map falls in the 0–5 t ha⁻¹ yr⁻¹ class and 33 percent exceeds 100 t ha⁻¹ yr⁻¹, the low class being the cells whose LS factor is zero. Figures 4–10 show the factors, Figure 11 the annual classes, and Figure 12 the twelve monthly maps.')
    add_table(doc, 'Table 6. Monthly RUSLE-estimated soil loss in 2025 with corrected Arnoldus erosivity and interpolated July and August cover. Means, medians, and 95th percentiles are in t ha⁻¹. Mean Rₘ is in MJ mm ha⁻¹ h⁻¹ month⁻¹.', ['Month', 'Mean Aₘ', 'Median', '95th percentile', 'Mean Cₘ', 'Mean Rₘ'], [['January', '0', '0', '0', '0.685', '0'], ['February', '0', '0', '0', '0.700', '0'], ['March', '0.600', '0.072', '2.51', '0.735', '24.2'], ['April', '1.10', '0.062', '4.52', '0.719', '53.7'], ['May', '3.33', '0.455', '13.7', '0.628', '170'], ['June', '27.7', '4.59', '107', '0.636', '1,515'], ['July', '65.4', '9.92', '261', '0.584', '3,689'], ['August', '21.5', '2.90', '88.4', '0.532', '1,293'], ['September', '8.97', '1.11', '36.6', '0.480', '581'], ['October', '7.10', '1.12', '27.5', '0.533', '444'], ['November', '0.207', '0.029', '0.816', '0.641', '10.7'], ['December', '0', '0', '0', '0.685', '0']])
    body(doc, 'On the 4,154,545 pixels with a valid June and a valid interpolated July, 48 percent are below 0.01 t ha⁻¹ in both months. The June median is 4.65 t ha⁻¹ and the July median is 9.92 t ha⁻¹, so July is higher because erosivity is higher and cover stays on the optical scale. Forty-four percent of these pixels have an LS factor of exactly zero, which is the combined slope-length and steepness factor rather than length alone, and soil loss on those cells is zero in every month. That group accounts for the values below 0.01. Interpolated July cover is above 0.15 everywhere in this set (Table 7). Ninety-six percent of the pixels have July cover above 0.40, and their median soil loss is 7.90 t ha⁻¹ in July and 3.76 t ha⁻¹ in June, with a median LS factor of 0.35, just above the large group of zero-LS cells.')
    add_table(doc, 'Table 7. June and July soil loss on the 4,154,545 pixels with interpolated July cover. Soil loss is in t ha⁻¹. The LS column is the combined slope-length and steepness factor, not L alone. No pixel in this set has July cover below 0.15.', ['July cover', 'Share', 'Share of the class below 0.01', 'Median July', 'Median June', 'Median LS factor'], [['0.15 to 0.40', '4.3%', '32%', '43.5', '17.0', '1.52'], ['above 0.40', '95.7%', '49%', '7.90', '3.76', '0.35']])
    body(doc, 'The principal annual figure uses the corrected Arnoldus erosivity, with the July and August cover interpolated from June and September. On the 4,154,545 pixels that are valid in all twelve months, the mean is 136 t ha⁻¹ yr⁻¹ and the median is 21.7 t ha⁻¹ yr⁻¹. The primary RUSLE scenario gives a gross soil-loss mass of 8.82 million t yr⁻¹, equivalent to approximately 6.08 million m³ yr⁻¹ when converted using the assumed bulk density of 1.45 t m⁻³. Radar cover on the same erosivity gives 87.2 t ha⁻¹ yr⁻¹, equivalent to 3.90 million m³ yr⁻¹ at that same density. The Renard and Freimund annual total, applied to the interpolated cover with the same monthly shares of rainfall, gives 346 t ha⁻¹ yr⁻¹, equivalent to 15.5 million m³ yr⁻¹ (Table 8). The line of SAVI on RVI, fitted outside July and August, has R² = 0.033 and has not been used.')
    add_table(doc, 'Table 8. Annual soil loss on the 4,154,545 pixels valid in all twelve months. The volume column is soil-loss mass divided by the assumed bulk density of 1.45 t m⁻³. It is not a measured erosion volume. The Arnoldus rows use the monthly maps. The Renard and Freimund row uses the same monthly rainfall shares and the interpolated cover.', ['Case', 'Mean (t ha⁻¹ yr⁻¹)', 'Median', 'Gross volume (million m³ yr⁻¹)'], [['Interpolated optical, Arnoldus', '136', '21.7', '6.08'], ['Radar cover, Arnoldus', '87.2', '12.8', '3.90'], ['Interpolated optical, Renard and Freimund', '346', '53.4', '15.5']])
    add_figure(doc, ((FIGURES / 'maps') / 'LS_2025.png'), 'Figure 4. Slope-length and steepness factor. LS means the combined factor, not length alone. Cells with no slope on the whole-metre elevation grid are exactly zero.')
    add_figure(doc, ((FIGURES / 'maps') / 'C_annual_baseline_2025.png'), 'Figure 5. Annual cover-management factor from the aligned baseline. The minimum on this layer is 0.284, so no pixel is below 0.15.')
    add_figure(doc, ((FIGURES / 'maps') / 'P_2025.png'), 'Figure 6. Support-practice factor. This layer is static through the year.')
    add_figure(doc, ((FIGURES / 'maps') / 'Cm_monthly_2025.png'), 'Figure 7. Monthly cover factor stored with the satellite stacks. January–June and September–December use SAVI. July and August use the radar index. The reported soil-loss maps replace those two months with cover interpolated from June and September.')
    add_figure(doc, ((FIGURES / 'maps') / 'Km_monthly_2025.png'), 'Figure 8. Monthly erodibility factor used inside the reported RUSLE product. Each month is stretched to its own Sentinel-1 VV percentiles, so a wetter month does not appear as a lower Km. The stretch is a heuristic, not a measurement of soil erodibility.')
    add_figure(doc, ((FIGURES / 'maps') / 'Cm_July_2025.png'), 'Figure 9. July cover from the stored radar index. This is the sensitivity layer. The reported July soil-loss map uses cover interpolated from June and September.')
    add_figure(doc, ((FIGURES / 'maps') / 'Km_July_2025.png'), 'Figure 10. July erodibility after the within-month stretch of Sentinel-1 VV. The stretch was not corrected for incidence angle or terrain.')
    add_figure(doc, ((FIGURES / 'maps') / 'SoilLoss_Arnoldus_annual_class_2025.png'), 'Figure 11. RUSLE-estimated annual soil loss for 2025, using corrected Arnoldus erosivity and July–August cover interpolated from June and September. The sum uses only pixels valid in all twelve months. Classes are 0–5, 5–15, 15–30, 30–50, 50–100, and greater than 100 t ha⁻¹ yr⁻¹. Grey inside the boundary is NoData. The frame is WGS 84 / UTM zone 45N.')
    add_figure(doc, ((FIGURES / 'maps') / 'SoilLoss_Arnoldus_monthly_2025.png'), 'Figure 12. Monthly RUSLE-estimated soil loss for 2025 using corrected Arnoldus erosivity. July and August cover is an interpolated scenario, not an observed canopy. The panels are model estimates, not field measurements. All panels share a scale from zero to the 98th percentile of the monthly values.')
    heading(doc, '6.3 Structural connectivity and a modelled delivery scenario', 2)
    body(doc, 'The corrected index is finite on all 4,576,196 cells of the watershed. Its mean is −7.73 and its median is −7.66, with a 5th to 95th percentile range of −9.62 to −6.63. The sediment delivery ratio has a mean of 0.00105 and a median of 0.000891, with a 5th to 95th percentile range of 0.000174 to 0.00210. A few cells reach an index of about −0.95 and a delivery ratio of 0.184. For that reason, a stretch from the minimum to the maximum paints the catchment almost in one colour. Figures 13 and 14 use the 2nd to 98th percentile.')
    body(doc, 'Applied to the principal annual map, the gross hillslope erosion is 8.82 million t yr⁻¹ and the delivered yield is 14,873 t yr⁻¹, or 1.03 × 10⁴ m³ yr⁻¹ at the assumed bulk density (Table 9). The delivery fraction is 0.00169. Radar cover on the same erosivity gives 9,388 t yr⁻¹, or 6,475 m³ yr⁻¹. Both figures are modelled sediment yield to cells on the boundary of the valid elevation grid. Those boundary cells are the outlets used here. They are not a surveyed outlet of the reservoir, and the shoreline of the reservoir was not masked. The yield is not a measured rate of siltation for Tilaiya Reservoir. At the median index of −7.66, the adopted sigmoid gives a delivery ratio of 0.00089. The same threshold and the same maximum, with k = 2, a value often used with this sigmoid (Hamel et al., 2015), give 0.013 at that cell. The connectivity raster was not recomputed. A change in the assumed bulk density alone, from 1.45 to 1.20 or 1.60 t m⁻³, changes the principal figure of 14,873 t yr⁻¹ to 1.24 × 10⁴ or 9,296 m³ yr⁻¹.')
    add_table(doc, 'Table 9. RUSLE soil-loss mass and modelled sediment delivery to the boundary of the valid grid. Both rows use corrected Arnoldus erosivity. The volume column divides that mass by an assumed bulk density of 1.45 t m⁻³. This is not a measured erosion volume and not a reservoir-siltation measurement.', ['Soil-loss map', 'Pixels', 'Mean A (t ha⁻¹ yr⁻¹)', 'Gross (t yr⁻¹)', 'Yield (t yr⁻¹)', 'Volume (m³ yr⁻¹)'], [['Interpolated cover, primary', '4,154,545', '136', '8,819,637', '14,873', '10,257'], ['Radar cover, sensitivity', '4,154,545', '87.2', '5,658,895', '9,388', '6,475']])
    add_figure(doc, ((FIGURES / 'maps') / 'IC_2025.png'), 'Figure 13. Borselli index of connectivity, weighted by mean monthly Cₘ. The colour stretch is the 2nd to 98th percentile. Higher values are more connected to the catchment outlet.')
    add_figure(doc, ((FIGURES / 'maps') / 'SDR_2025.png'), 'Figure 14. Sediment delivery ratio from the connectivity index. The colour stretch is the 2nd to 98th percentile. Higher values deliver a larger fraction of local soil loss.')
    heading(doc, '6.4 Surrogate recovery of the annual RUSLE surface', 2)
    body(doc, 'On the 3,809 holdout points, the Reduced Integrated stack has R² = 0.832, RMSE = 22.19 t ha⁻¹ yr⁻¹, and MAE = 1.02 t ha⁻¹ yr⁻¹ (Table 10). Out-of-fold performance on the 8,888 training points is much higher (R² = 0.983, RMSE = 2.96, MAE = 0.71). The stack is a surrogate model, or emulation, of the annual RUSLE surface. The scores are surrogate-model diagnostics. They are not a spatially validated prediction of erosion. The target is that model-generated value, and the predictors include factors of the same surface, so the scores measure how well the learners reproduce the reference RUSLE estimate. They do not measure accuracy against erosion or sediment yield. The multilayer perceptron alone has holdout R² = 0.920, RMSE = 15.33, and MAE = 1.01. CatBoost, XGBoost, and Random Forest are weaker as single models (holdout R² 0.548, 0.451, and 0.443). The 27 holdout points with a reference RUSLE value above 100 t ha⁻¹ yr⁻¹, 0.7 per cent of the holdout, supply 99.5 per cent of the reduced-stack squared error and 98.1 per cent of the dynamic-stack squared error. Trees do not extrapolate past the training maximum of 909 t ha⁻¹ yr⁻¹, and the holdout reaches 2,769. The holdout points were drawn at random inside the watershed, so neighbouring cells can fall on opposite sides of the split (Roberts et al., 2017; Ploton et al., 2020). A spatially blocked holdout and a log-transformed target were not run. Ridge weights on the blend are CatBoost 0.702, perceptron 0.567, XGBoost −0.085, and Random Forest −0.167, with intercept −0.097.')
    body(doc, 'Holdout MAE near 1 t ha⁻¹ yr⁻¹ means that a typical point is close to the RUSLE value. Holdout RMSE is large because the test set contains the extreme tail. The largest training soil loss is 909 t ha⁻¹ yr⁻¹. The largest holdout soil loss is 2,769 t ha⁻¹ yr⁻¹. Three holdout points exceed 500 t ha⁻¹ yr⁻¹, and 27 exceed 100 t ha⁻¹ yr⁻¹. The stack under-predicts the most extreme points. Figure 15 shows the reference RUSLE value against the stack prediction for the Reduced Integrated model. Figure 16 shows the same comparison for the Dynamic Integrated model.')
    add_table(doc, 'Table 10. Reduced Integrated models. Predictors are LS, SOC, C, P, NDVI, and K. RMSE and MAE are in t ha⁻¹ yr⁻¹. The holdout has 3,809 points.', ['Model', 'Set', 'R²', 'RMSE', 'MAE'], [['Stack, out of fold', 'Training blocks', '0.983', '2.96', '0.71'], ['Stack', 'Holdout', '0.832', '22.19', '1.02'], ['Multilayer perceptron', 'Holdout', '0.920', '15.33', '1.01'], ['CatBoost', 'Holdout', '0.548', '36.35', '1.47'], ['XGBoost', 'Holdout', '0.451', '40.08', '1.76'], ['Random Forest', 'Holdout', '0.443', '40.34', '1.94']])
    add_figure(doc, ((FIGURES / 'Reduced_Integrated') / 'observed_vs_predicted.png'), 'Figure 15. Reference annual RUSLE estimate against the Reduced Integrated stack on the holdout. The squared error is dominated by a small number of very large reference values. The vertical axis is the model-generated RUSLE surface, not a field measurement.')
    add_figure(doc, ((FIGURES / 'Dynamic_Integrated') / 'observed_vs_predicted.png'), 'Figure 16. Reference annual RUSLE estimate against the Dynamic Integrated stack on the same holdout points. Holdout R² is 0.702. The target is the annual RUSLE layer, not the 2025 monthly sum and not measured sediment.')
    body(doc, 'Dynamic Integrated has holdout R² = 0.702, RMSE = 29.49, and MAE = 1.77 on the same annual RUSLE target (Table 11). Its perceptron member again fits the holdout more closely than the blend (R² = 0.878, RMSE = 18.90). Ridge weights are CatBoost 0.903, perceptron 0.389, XGBoost 0.042, and Random Forest −0.282, with intercept −0.295. This comparison changes both the predictors and their relationship to the target, because the target was calculated with annual K and C, while the second stack uses R, Kₘ, Cₘ, RVI, and SAVI instead of K, C, and NDVI. The lower score is evidence about compatibility with that annual target. It is not evidence that monthly or dynamic predictors are inferior, and it is not a general test of whether dynamic modelling works. A fair test would predict the 2025 monthly maps, or the dynamic annual sum, or measured sediment. Those three tests were not run.')
    add_table(doc, 'Table 11. Dynamic Integrated models. Predictors are LS, R, Kₘ, Cₘ, P, RVI, SAVI, and SOC. RMSE and MAE are in t ha⁻¹ yr⁻¹.', ['Model', 'Set', 'R²', 'RMSE', 'MAE'], [['Stack, out of fold', 'Training blocks', '0.964', '4.31', '1.20'], ['Stack', 'Holdout', '0.702', '29.49', '1.77'], ['Multilayer perceptron', 'Holdout', '0.878', '18.90', '2.01'], ['CatBoost', 'Holdout', '0.466', '39.52', '1.65'], ['XGBoost', 'Holdout', '0.411', '41.51', '1.86'], ['Random Forest', 'Holdout', '0.390', '42.22', '2.55']])
    body(doc, 'Holdout error is not uniform across the erosion classes (Table 12). For the Reduced Integrated stack, MAE is 0.37 t ha-1 yr-1 in E1 (n = 2,319) and rises only to 2.46 in E5 (n = 74). In E6, the 27 points above 100 t ha-1 yr-1, MAE is 74 and RMSE is 263. Their mean reference RUSLE value is 334 and the mean prediction is 270. Dynamic Integrated shows the same pattern, with E6 MAE 113. The aggregate RMSE is therefore the extreme class, not the error on a typical point. One random seed and one stratified holdout were used. The holdout points were not withheld by spatial block, so the reported R² is not a spatially blocked validation. No confidence interval, repeated spatial cross-validation, or log-transformed target was calculated.')
    add_table(doc, 'Table 12. Reduced Integrated holdout error by annual RUSLE class. MAE and RMSE are in t ha-1 yr-1.', ['Class', 'n', 'Mean reference', 'Mean predicted', 'MAE', 'RMSE'], [['E1, 0-5', '2,319', '0.63', '0.63', '0.37', '1.67'], ['E2, 5-15', '862', '9.24', '9.29', '0.42', '0.86'], ['E3, 15-30', '390', '20.8', '20.9', '0.75', '1.12'], ['E4, 30-50', '137', '37.1', '37.5', '1.38', '2.35'], ['E5, 50-100', '74', '64.9', '65.9', '2.46', '3.09'], ['E6, above 100', '27', '334', '270', '74.0', '263']])
    heading(doc, '6.5 Attributions inside the XGBoost members', 2)
    body(doc, 'Mean absolute SHAP on the Reduced Integrated XGBoost model attributes the largest share to LS. The unrounded value is 10.326 t ha⁻¹ yr⁻¹, then P (2.686), SOC (2.347), K (0.983), C (0.493), and NDVI (0.105) (Table 13 and Figures 17–20). The Dynamic Integrated file, from a separate run, gives LS 10.329. The two numbers round to 10.33 and are not a copied array; they differ by 0.003 because both models see the same LS-dominated target. Values of LS, P, C, and K above the holdout median increase predicted soil loss. Values of SOC above the median decrease it. NDVI has little separate effect once C is in the model. The aligned annual C layer has a minimum of 0.284 across the watershed, so the absence of holdout C below 0.15 is a property of that layer, not only of the sample draw. The attribution explains the XGBoost member and the model-derived RUSLE target only. It does not describe the ridge blend or the perceptron, it is not a causal effect, and it is not evidence of a measured control on erosion. LS is also a factor of the RUSLE target, so a large LS attribution partly recovers that construction. Stability across resampled holdouts was not tested.')
    add_table(doc, 'Table 13. Mean absolute SHAP for the Reduced Integrated XGBoost member on 3,809 holdout points. Values are model attributions, not causal effects.', ['Feature', 'Mean absolute SHAP (t ha⁻¹ yr⁻¹)'], [['LS', '10.326'], ['P', '2.69'], ['SOC', '2.35'], ['K', '0.98'], ['C', '0.49'], ['NDVI', '0.11']])
    add_figure(doc, (((FIGURES / 'Reduced_Integrated') / 'shap') / 'shap_summary.png'), 'Figure 17. TreeSHAP summary for the Reduced Integrated XGBoost model on the holdout. Each point is one holdout location. LS dominates the spread of predicted soil loss.')
    add_figure(doc, (((FIGURES / 'Reduced_Integrated') / 'shap') / 'shap_importance.png'), 'Figure 18. Mean absolute SHAP for the Reduced Integrated XGBoost member. The values are attributions for that member, not causal effects, and they do not describe the ridge blend.')
    add_figure(doc, (((FIGURES / 'Reduced_Integrated') / 'shap') / 'shap_dependence_LS.png'), 'Figure 19. SHAP dependence on the LS factor for the Reduced Integrated XGBoost member. Higher LS increases predicted soil loss.')
    add_figure(doc, (((FIGURES / 'Reduced_Integrated') / 'shap') / 'shap_dependence_C.png'), 'Figure 20. SHAP dependence on annual cover for the Reduced Integrated XGBoost member. No holdout point has annual C below 0.15.')
    body(doc, 'The same holdout, explained for the Dynamic Integrated XGBoost model, keeps LS first. The unrounded mean absolute SHAP is 10.329 t ha⁻¹ yr⁻¹, against 10.326 in the Reduced Integrated file (Table 14 and Figures 21–24). Support practice remains second (2.59). The within-month stretch Km is third (2.04), ahead of SOC (1.44). SAVI (0.37) and Cm (0.22) are small. Rainfall erosivity R (0.07) and RVI (0.06) add almost nothing. Values above the holdout median increase predicted loss for LS, P, Km, and Cm, and decrease it for SOC and SAVI. The sign on Cm matches the RUSLE cover factor: a higher Cm is less protection. The sign on SAVI runs the other way, as expected for a vegetation index. No holdout point has Cm below 0.15; the mean holdout Cm is 0.577. The watershed July map does reach the cover floor, so the holdout mean is not a description of July. This ranking describes the Dynamic XGBoost member only.')
    add_table(doc, 'Table 14. Mean absolute SHAP for the Dynamic Integrated XGBoost member on the same 3,809 holdout points. Values are model attributions, not causal effects.', ['Feature', 'Mean absolute SHAP (t ha⁻¹ yr⁻¹)'], [['LS', '10.329'], ['P', '2.59'], ['Km', '2.04'], ['SOC', '1.44'], ['SAVI', '0.37'], ['Cm', '0.22'], ['R', '0.07'], ['RVI', '0.06']])
    add_figure(doc, (((FIGURES / 'Dynamic_Integrated') / 'shap') / 'shap_summary.png'), 'Figure 21. TreeSHAP summary for the Dynamic Integrated XGBoost model on the holdout. The LS factor remains dominant. Monthly erosivity and RVI contribute little at the sample points.')
    add_figure(doc, (((FIGURES / 'Dynamic_Integrated') / 'shap') / 'shap_importance.png'), 'Figure 22. Mean absolute SHAP for the Dynamic Integrated XGBoost member. Km ranks third. R and RVI are the smallest terms.')
    add_figure(doc, (((FIGURES / 'Dynamic_Integrated') / 'shap') / 'shap_dependence_LS.png'), 'Figure 23. SHAP dependence on the LS factor for the Dynamic Integrated XGBoost member. The pattern follows the same LS-dominated target as Figure 19.')
    add_figure(doc, (((FIGURES / 'Dynamic_Integrated') / 'shap') / 'shap_dependence_Cm.png'), 'Figure 24. SHAP dependence on mean monthly cover for the Dynamic Integrated XGBoost member. No holdout point has Cm below 0.15.')
    heading(doc, '6.6 Comparison with published rates', 2)
    body(doc, 'Table 15 sets the 2025 maps beside published rates for this region and for RUSLE studies more generally. The rows are not the same quantity. Ghosh et al. (2025) and Biswas and Pani (2015) report annual gross soil loss for the Damodar and the Barakar, Borrelli et al. (2021) report medians across many modelled studies, Central Water Commission (2021) reports a reservoir volume. Sardar et al. (2014) is cited as a SWAT study, and its printed rate is not given a row because the unit was not verified, and Pandey et al. (2007) report how close a USLE sediment yield came to measurements at Karso. The rows for this study are hillslope soil loss and a structural yield on the 715 km² mask for one year.')
    add_table(doc, 'Table 15. Published rates set beside the 2025 results. Soil loss is in t ha⁻¹ yr⁻¹. Volumes are annual. The rows do not share a boundary, a year, or a measurement.', ['Source', 'What was estimated', 'Value'], [['Present study', 'RUSLE-estimated mean annual soil loss, 715 km², 2025', '136 (median 21.7)'], ['Present study', 'Area above 100 t ha⁻¹ yr⁻¹', '33 percent'], ['Present study', 'July mean, from Table 6', '65.4'], ['Present study', 'Soil-loss mass and equivalent volume at 1.45 t m⁻³; structural yield', '8.82 million t; 6.08 million m³; 1.03 × 10⁴ m³'], ['Ghosh et al. (2025)', 'Damodar basin, annual RUSLE mean', '12.86 in 2017; 12.06 in 2024'], ['Biswas and Pani (2015)', 'Barakar basin, area above 100', '0.08 percent'], ['Borrelli et al. (2021)', 'Median gross rate, many studies', '9.6 USLE; 12.6 RUSLE'], ['Central Water Commission (2021)', 'Mean live-storage loss', '1.01 million m³ yr⁻¹'], ['Pandey et al. (2007)', 'Karso, USLE yield against measurements', 'Deviation 1.37–13.85 percent']])
    body(doc, 'The median on this map, 21.7 t ha⁻¹ yr⁻¹, lies close to the Damodar basin means of 12.06 and 12.86 t ha⁻¹ yr⁻¹ (Ghosh et al., 2025) and to the global RUSLE median of 12.6 t ha⁻¹ yr⁻¹ (Borrelli et al., 2021), but the mean of 136 t ha⁻¹ yr⁻¹ is about ten times those rates. The radar-cover mean on the same erosivity, 87.2 t ha⁻¹ yr⁻¹, is still several times the Damodar means, so the gap is not produced only by the June–September interpolation. The mean is high because 33 percent of the pixels exceed 100 t ha⁻¹ yr⁻¹, whereas Biswas and Pani (2015) found that class on 0.08 percent of the Barakar. Those two shares are not a change through time: their map is an annual RUSLE for the whole Barakar, and this map uses 2025 rainfall, Arnoldus erosivity of 6,854 to 12,083 MJ mm ha⁻¹ h⁻¹ yr⁻¹, and a 12.5 m headwater grid on which 48 percent of the area falls in the 0–5 class because the LS factor is exactly zero and one third of the area is above 100. A basin mean near 12 t ha⁻¹ yr⁻¹ does not show that split.')
    body(doc, 'The twelve monthly means in Table 6 add to 136 t ha⁻¹. June, July and August contribute 27.7, 65.4 and 21.5, together 115 t ha⁻¹, and July alone is almost half of the annual mean, a seasonal concentration that the annual Damodar and Barakar maps do not resolve. One rainfall cell peaks in June and the other four peak in July. Pandey et al. (2007) remain the nearby study in which a USLE yield was compared with measurements, with a deviation of 1.37 to 13.85 percent at Karso, and no equivalent check was made here.')
    body(doc, 'The primary RUSLE scenario gives a gross soil-loss mass of 8.82 million t yr⁻¹, equivalent to approximately 6.08 million m³ yr⁻¹ when converted using the assumed bulk density of 1.45 t m⁻³. That equivalent volume is about six times the Central Water Commission (2021) live-storage loss of 1.01 million m³ yr⁻¹. The Sardar et al. (2014) rate is not used in this comparison, because the typeset unit could not be verified. The structural yield is 1.03 × 10⁴ m³ yr⁻¹. The equivalent soil volume sits above the Commission figure, while the structural yield sits below it. The difference is the mean delivery ratio of 0.00105. Matching 1.01 million m³ yr⁻¹ from this equivalent volume would need a mean ratio near 0.17. The yield is a structural delivery scenario for sediment reaching the mask edge. It is not a measured sediment yield and not reservoir siltation. The comparison with the published Tilaiya rates is context for that scenario, not a validation of it. Section 7.4 explains why the Sardar rate is omitted. These three results, the monthly concentration, the split between a moderate median and a high mean, and the gap between hillslope volume and reservoir volume, are the findings that the earlier annual maps and the reservoir models do not contain together. Biswas and Pani (2015) did not calculate a delivery ratio, and Sardar et al. (2014) and Dutta et al. (2017) routed sediment in SWAT at the scale of reservoir inflow. The stacking scores in Section 6.4 emulate the annual RUSLE surface from its own factors. They do not estimate measured erosion.')

    heading(doc, '6.7 Scenario envelope', 2)
    body(doc, 'Table 16 collects the annual scenarios that were calculated. The mean of 136 t ha⁻¹ yr⁻¹ and the structural volume of 1.03 × 10⁴ m³ yr⁻¹ are one case: integer-metre elevation, the published LS raster, heuristic Km, interpolated July and August cover, and the corrected Arnoldus total. On the 4,138,768 pixels where base K and Km are both finite, holding erodibility at base K changes the mean from 136 to 119 t ha⁻¹ yr⁻¹ and the median from 22.8 to 20.4. The equivalent volume at 1.45 t m⁻³ changes from 6.08 to 5.32 million m³ yr⁻¹, and the structural yield from 1.03 × 10⁴ to 9.04 × 10³ m³ yr⁻¹. The 0–5 class remains 48 percent of that set, and the class above 100 remains 31 percent. Heuristic Km therefore rescales this scenario by about 14 percent. It does not create the gap between the mean and the median. Changing only the assumed bulk density from 1.45 to 1.20 or 1.60 t m⁻³ changes the reported structural volume to 1.24 × 10⁴ or 9.30 × 10³ m³ yr⁻¹ and leaves the soil-loss map unchanged.')
    body(doc, 'A second case replaces only the LS factor. The original LS tool is not among the project scripts, so a standard equation was scored against the published LS raster on the integer-metre DEM. Upslope length is the D8 accumulation count times 12.5 m. The length exponent is 0.2, 0.3, 0.4, or 0.5 as slope crosses 1, 3, and 5 percent. Steepness follows McCool: 10.8 sin β + 0.03 below 9 percent slope, and 16.8 sin β − 0.50 at 9 percent and above. The equation is then multiplied by 1.12, the median ratio of published LS to the equation where both are positive. Pearson correlation with the published LS is 0.77, so this is a sensitivity equation and not a reconstruction of the published raster. On the integer-metre DEM the equation still leaves 38 percent of cells at LS exactly zero, against 44 percent in the published raster. The ALOS tiles available for this catchment are also stored in whole metres. FABDEM was not used.')
    body(doc, 'Copernicus GLO-30 was bilinearly placed on the same 12.5 m grid. Under the same equation, 1.2 percent of cells have LS exactly zero. Of the cells whose published LS is exactly zero, 88 percent have a Copernicus D8 slope steeper than 0.5 degrees, and the median slope on those cells is 3.2 percent. The annual mean is 103 t ha⁻¹ yr⁻¹ on the integer-metre DEM and 119 on Copernicus, with medians of 64 and 62. Equivalent volumes at 1.45 t m⁻³ are 4.60 and 5.30 million m³ yr⁻¹. The structural yields quoted here, 5.42 × 10³ and 5.90 × 10³ m³ yr⁻¹, multiply the new soil-loss map by the existing delivery grid. Flow paths were not rebuilt on Copernicus, so this is a soil-loss sensitivity and not a complete connectivity sensitivity. July remains the peak month. On Copernicus the July mean is 57.1 t ha⁻¹ and the July median is 29.2, against 23.7 and 13.2 in June. The 0–5 class falls to 7.8 percent, while the class above 100 remains 35 percent. The continuous surface removes most of the exact zeros. It leaves a large high class, and it does not reproduce the published median of 21.7, which belongs to the published LS raster.')
    add_table(doc, 'Table 16. Scenario envelope for 2025. Means and medians are in t ha⁻¹ yr⁻¹. Gross volume is soil-loss mass divided by the assumed bulk density of 1.45 t m⁻³ and is reported in million m³ yr⁻¹. It is not a measured erosion volume. Structural yield is in m³ yr⁻¹ and uses the existing delivery grid, including for the Copernicus row. Static K and the two standard-LS rows use 4,138,768 pixels. The reported, radar, and Renard–Freimund rows use the 4,154,545 twelve-month pixels.', ['Case', 'Mean', 'Median', 'Gross volume', 'Structural yield'], [['Reported Km and published LS', '136', '21.7', '6.08', '1.03 × 10⁴'], ['Static K and published LS', '119', '20.4', '5.32', '9.04 × 10³'], ['Standard LS on integer-metre DEM', '103', '64', '4.60', '5.42 × 10³'], ['Standard LS on Copernicus GLO-30', '119', '62', '5.30', '5.90 × 10³'], ['Radar cover and Arnoldus', '87.2', '12.8', '3.90', '6.48 × 10³'], ['Interpolated cover and Renard–Freimund', '346', '53.4', '15.5', '2.60 × 10⁴']])
    body(doc, 'Because the scenario cases do not all use identical valid-pixel support, their statistics should be interpreted as sensitivity comparisons rather than as strictly like-for-like estimates. The calculated means in Table 16 span 87 to 346 t ha⁻¹ yr⁻¹. The calculated structural yields span 5.42 × 10³ to 2.60 × 10⁴ m³ yr⁻¹. Every equivalent volume in the table lies above the Central Water Commission live-storage loss of 1.01 million m³ yr⁻¹, and every structural yield lies far below it. Alternative support-practice factors, other cover-factor coefficients, and a delivery sigmoid fitted to a reservoir rate were not calculated.')
    body(doc, 'The annual sum uses 4,154,545 pixels, 90.8 percent of the watershed. The other 421,649 watershed pixels lack at least one month (Figure 25 and Table 17). Their mean elevation is 411 m, against 388 m for the pixels in the annual sum, and their median elevation is 383 m against 366 m. The share of cells with D8 slope exactly zero is 38 percent in the annual set and 39 percent outside it. October NDVI has median 0.67 in both groups, and the annual cover factor has median 0.70 and 0.69. The excluded cells sit slightly higher on the plateau. They are not a steeper or less vegetated subset. Monthly means in Table 6 still use the pixels valid in that month. The June–July comparison in Section 6.2 uses the annual support.')
    add_table(doc, 'Table 17. Pixels inside and outside the twelve-month annual sum. Elevation is in metres. NDVI is the October median. C is the annual cover factor.', ['Group', 'Pixels', 'Mean elevation', 'Median elevation', 'D8 slope zero', 'October NDVI', 'Annual C'], [['In the annual sum', '4,154,545', '388', '366', '38 percent', '0.67', '0.70'], ['Excluded', '421,649', '411', '383', '39 percent', '0.67', '0.69']])
    add_figure(doc, ((FIGURES / 'maps') / 'annual_support_mask.png'), 'Figure 25. Pixels used in the twelve-month annual sum, and watershed pixels excluded because at least one month is missing. The frame is WGS 84 / UTM zone 45N.')
    heading(doc, '7. Discussion', 1)
    body(doc, 'The July median is set out in Section 6.2 and Table 7, where June and July were calculated with the same equation. Section 6.3 compares the modelled delivery with the reservoir surveys, Section 6.6 and Table 15 place the annual mean and the modelled volume next to the published rates, and Section 6.4 reports how closely a stack emulates the annual RUSLE surface.')
    heading(doc, '7.1 What the monthly maps change', 2)
    body(doc, 'On the reported maps, the median is 9.92 t ha⁻¹ in July and 4.65 t ha⁻¹ in June. July is higher because the monthly share of Arnoldus erosivity is higher and the cover factor remains on the optical scale. Forty-eight per cent of the shared pixels lie below 0.01 t ha⁻¹ in both months. Forty-four per cent have an LS factor of exactly zero, because the elevation is stored in whole metres and the flat cells have no slope. Those zeros are present in every month. They account for the low tail. They do not reverse the increase from June to July. In the present paper, LS is the combined factor of slope length and steepness.')
    body(doc, 'Radar cover was not used in the reported maps for July and August. At the sample points, the mean RVI is more than twice the mean SAVI, and a line of SAVI on RVI fitted outside July and August has R² = 0.033. Unscaled radar cover also places 22.5 per cent of the July pixels on the floor of 0.001. July SAVI from the two clear scenes is available on only 114,325 of the annual pixels, and those scenes therefore cannot fill the month. The reported cover is the interpolation between June and September. On the 4,154,545 pixels that are valid in all twelve months, that choice gives 136 t ha⁻¹ yr⁻¹. The same erosivity with radar cover gives 87.2 t ha⁻¹ yr⁻¹. The pixel-weighted mean erosivity rises from 1,515 MJ mm ha⁻¹ h⁻¹ in June to 3,689 in July, and July remains the peak month in the mean.')
    body(doc, 'The erosivity inherits the 0.25° grid of the India Meteorological Department. The rainfall maps at 12.5 m are blocky by construction. They support a calculation for the catchment. They do not resolve convective cells, valley winds, or the difference between two neighbouring hillslopes. The peak of Cell 1 in June, and of the other cells in July, is a real feature of this grid and of this year. It would not be seen in a single hyetograph of the catchment mean. The grid is still too coarse for siting a farm pond.')
    heading(doc, '7.2 Stacking model', 2)
    body(doc, 'Section 6.4 shows how closely a stack emulates the annual RUSLE surface from the factors of that surface. The R², RMSE, and MAE values are surrogate-model diagnostics. The holdout was not spatially blocked, so these scores are not a spatially validated prediction of erosion. They have not been used to alter the 2025 soil-loss maps, and they do not measure accuracy for erosion or sediment yield.')
    heading(doc, '7.3 What SHAP can and cannot say', 2)
    body(doc, 'Section 6.5 gives the attributions for the XGBoost members. Those values explain the member and the model-derived RUSLE target. They are not causal effects, and they are not measured controls on erosion. The LS factor is 10.326 and 10.329 t ha⁻¹ yr⁻¹ in the two files. Km ranks third in the member that uses the monthly factors. That rank can follow slope or aspect, because Km is a within-month stretch of Sentinel-1 backscatter that has not been corrected for incidence angle or terrain. The annual cover layer never falls below 0.284, and the target therefore has no contrast of the kind expected between forest and open range (Renard et al., 1997).')
    heading(doc, '7.4 Sediment delivery', 2)
    body(doc, 'The delivery ratio is near 0.001 because the connectivity index is very low. The median index is −7.66. With the sigmoid centred at 0.5 and a scale of 1.2, almost every cell falls on the low end of the curve, so the delivery ratio is about 10⁻³. Three choices produce this result. Flow paths run to the edge of the valid grid rather than to a channel or the reservoir shore, so the downslope distance at 12.5 m contains hundreds to thousands of cells. Slope and cover weight are not allowed to fall below 0.001. The elevation is stored in whole metres, so flat cells still add many small terms to the downslope sum. The parameters SDRmax = 0.8, IC₀ = 0.5, and k = 1.2 were taken from the literature. Vigiak et al. (2012) treat this type of delivery ratio as a value to be calibrated. It was not calibrated here.')
    body(doc, 'The northern plateau is stored in whole metres, and a large share of its cells have no unique downslope neighbour. Routing those flats only towards cells that already drain, and only at equal or lower elevation, removes the parallel bands produced by an artificial micro-slope. The remaining grain on the connectivity map is the integer elevation surface, not a stripe artefact. Paths still end at the edge of the watershed mask. The yield of 1.03 × 10⁴ m³ yr⁻¹ is a structural delivery scenario for the mask edge. A surveyed reservoir shoreline was not used. Gross erosion of 8.82 million t yr⁻¹ and delivered yield of 14,873 t yr⁻¹ answer different questions. The first identifies where soil is detached. The second, under these parameters, says that only a thin fraction of that detachment is structurally connected to the outlet in a single year.')
    body(doc, 'The primary RUSLE scenario gives a gross soil-loss mass of 8.82 million t yr⁻¹, equivalent to approximately 6.08 million m³ yr⁻¹ when converted using the assumed bulk density of 1.45 t m⁻³ (Table 8). This volume is not a measured erosion volume. Sardar et al. (2014) print a Tilaiya rate in the publisher abstract as 0.76 mm3/year. The typeset PDF was not available, so that rate is omitted from the numerical comparison. Central Water Commission (2021), publication CWC/2021/147, is a satellite survey of live storage, not a weekly storage bulletin. It reports a 2021 live capacity of 131.235 MCM at full reservoir level against an original 199.89 MCM, a loss of 68.655 MCM (34.3 per cent) over 68 years, or 1.01 million m³ yr⁻¹. Earlier live capacities in that report are 150.55 MCM (satellite, 1996–97), 140.47 MCM (hydrographic, 1997–98), and 138.43 MCM (satellite, 2003–04). The survey has no ground check. The 7 October 2021 storage bulletin lists Tilaiya live capacity at full reservoir level as 0.142 billion m³, and the storage on that day as the same 0.142 billion m³. It does not contain 131.235. Matching 1.01 million m³ yr⁻¹ from this equivalent soil volume would need a mean delivery ratio near 0.17. The mean of the delivery-ratio grid is 0.00105, about 160 times smaller than 0.17. The modelled yield in this reported scenario is therefore 1.03 × 10⁴ m³ yr⁻¹. Section 6.7 keeps every calculated equivalent volume above the Commission live-storage loss and every structural yield far below it. The remaining error is in the delivery calculation: paths end at the mask edge, slope and cover are floored at 0.001 on a whole-metre elevation grid, and IC₀ and k were not calibrated to the survey. The connectivity raster was not rebuilt. The Copernicus soil-loss case in Section 6.7 uses this same delivery grid. It is a sensitivity of the soil-loss estimate. It is not an independent recalculation of the sediment-connectivity model. The reservoir area at maximum conservation pool is 38.45 km² (Damodar Valley Corporation, n.d.).')
    heading(doc, '7.5 Limits', 2)
    body(doc, 'The adopted erosivity equation has a published source, but it was not fitted at Tilaiya, and storm EI30 was not calculated. Because the elevation is stored in whole metres, 44 percent of the shared pixels have an LS factor of exactly zero, and connectivity slopes and weights are held at a minimum of 0.001, which keeps the index near −7.7. Flow paths end at the mask edge rather than at a Sentinel-1 shoreline, and the delivery-equation parameters were not calibrated to the Central Water Commission (2021) live-storage loss. Copernicus GLO-30 and a static-K case were calculated in Section 6.7. FABDEM, an unrounded ALOS surface, a minimum slope inside the published LS raster, routing to a Sentinel-1 shoreline, and calibration of the delivery equation to the storage survey were not carried out. The Copernicus structural yields use the existing delivery grid, so they do not test a rebuilt connectivity model. The stacking scores are surrogate-model diagnostics. The holdout was a random stratified split and was not spatially blocked, and no repeated spatial cross-validation or confidence interval was calculated. The scripts, rasters, and tables have not been deposited in a public archive, and this paper is not a public reproduction package. Under the reported scenario the annual mean is 136 t ha⁻¹ yr⁻¹. Across the cases in Table 16 the means span 87 to 346 t ha⁻¹ yr⁻¹.')
    heading(doc, '8. Conclusions', 1)
    body(doc, 'The 2025 results are a set of RUSLE scenarios for one year, not a validated sediment budget. In the reported scenario the mean is 136 t ha⁻¹ yr⁻¹ and the median is 21.7, with June, July and August carrying most of the annual total and July alone at 65.4 t ha⁻¹. Static K lowers the mean to 119 and leaves the median near 20. A standard slope-length equation gives a mean of 103 and a median of 64 on the integer-metre elevation, and a mean of 119 and a median of 62 on Copernicus GLO-30. Radar cover and the Renard–Freimund annual total extend the calculated means from 87 to 346 t ha⁻¹ yr⁻¹. The published median near 22 is tied to the published LS raster, in which 44 percent of the common-support pixels are exactly zero because elevation is stored in whole metres. That zero share falls to 1.2 percent on Copernicus, while the class above 100 t ha⁻¹ yr⁻¹ remains about one third of the area.')
    body(doc, 'Every equivalent volume in Table 16, obtained by dividing soil-loss mass by 1.45 t m⁻³, lies above the Central Water Commission live-storage loss, and every structural yield lies far below it. The Sardar et al. (2014) rate is not used as a benchmark, because the typeset PDF was not available and the abstract unit could not be verified. The reported structural volume of 1.03 × 10⁴ m³ yr⁻¹ is one point in that set, from 5.42 × 10³ to 2.60 × 10⁴ m³ yr⁻¹, and it uses an uncalibrated delivery grid that ends at the mask edge. In the absence of plot-scale erosion measurements, sediment-gauge records, and reservoir bathymetry, this study should be read as a physically informed framework for monthly RUSLE-based soil loss and structural sediment connectivity. The results describe the seasonal and spatial behaviour of modelled erosion potential. They do not report directly measured erosion or reservoir sedimentation. The stacking results are surrogate-model diagnostics. A spatially blocked holdout was not run. The scripts, rasters, tables, metadata, and checksum inventory are deposited at https://github.com/mktiwari123/Tilaiya-2A219-soil-erosion-2025.')
    heading(doc, 'CRediT authorship contribution statement', 1)
    body(doc, 'Mukesh Kumar Tiwari: conceptualisation, methodology, software, formal analysis, visualisation, writing — original draft. Prabhat Kumar Guru: writing — review and editing.', first_line=False)
    heading(doc, 'Declaration of competing interest', 1)
    body(doc, 'The authors declare that they have no known competing financial interests or personal relationships that could have appeared to influence the work reported in this paper.', first_line=False)
    heading(doc, 'Data availability', 1)
    body(doc, 'Sentinel-1 and Sentinel-2 scenes are the public Copernicus collections COPERNICUS/S1_GRD and COPERNICUS/S2_SR_HARMONIZED. IMD daily rainfall grids and SoilGrids layers are public. The analysis scripts, scenario tables, soil-loss rasters, metadata, and checksum inventory are deposited at https://github.com/mktiwari123/Tilaiya-2A219-soil-erosion-2025. A spatially blocked holdout was not run. The annual baseline rasters used as static inputs were not modified.', first_line=False)
    heading(doc, 'Acknowledgements', 1)
    body(doc, 'The India Meteorological Department daily gridded rainfall, Copernicus Sentinel-1 and Sentinel-2 data, the ALOS PALSAR digital elevation model, ISRIC SoilGrids, and the Damodar Valley Corporation reservoir summary made this analysis possible.', first_line=False)
